local AddOn, AQ = ...

-- Reads AllQuest's bundled quest database (Data/DB_*.lua, generated by devtools/build_data.py)
-- and decides which quests are shown for the current character.
--
-- AQ.DB layout:
--   quests[id] = { name, level, requiredLevel, maxLevel, raceMask, classMask, specialFlags,
--                  preQuestSingle, preQuestGroup, exclusiveTo, parentQuest,
--                  requiredSkill {id, value}, requiredMinRep {faction, value}, requiredMaxRep {faction, value} }
--   npcs[id]   = { name, subName, friendlyTo ("A" | "H" | "AH") }       objs[id] = name
--   items[id]  = { itemName, "Dropped by ..." }       dungeons[areaId] = dungeonName
--   maps[uiMapId] = { { x, y (0-100), kind, giverId, { questId, ... } }, ... }
--       kind: "n" NPC, "o" object, "i" dropped item (id = item), "d" dungeon entrance (id = dungeon area)
--   raceMask[raceId] = bit mask used by the race fields above
local Data = {}
AQ.Data = Data

Data.ready = false
Data.mapCount = 0
Data.entryCount = 0
Data.questCount = 0

local DB
local raceMask, classFlag, faction

local function HasBit(mask, flag)
    return (not mask) or mask == 0 or (mask % (flag * 2)) >= flag
end

function Data.Init()
    DB = AQ.DB
    if not next(DB.quests) then
        AQ.Print("|cffff4040The quest database is missing (Data/DB_*.lua), so there are no markers.|r")
        return
    end
    for _, list in pairs(DB.maps) do
        Data.mapCount = Data.mapCount + 1
        Data.entryCount = Data.entryCount + #list
    end
    for _ in pairs(DB.quests) do Data.questCount = Data.questCount + 1 end
    raceMask = DB.raceMask[select(3, UnitRace("player"))] or 0
    classFlag = 2 ^ ((select(3, UnitClass("player"))) - 1)
    faction = UnitFactionGroup("player")
    Data.ready = true
    AQ.RefreshAll()
end

---------------------------------------------------------------------------------------------
-- Lookups

-- Title and subtitle for a giver spot's tooltip.
function Data.StarterInfo(entry)
    local kind, id = entry.kind, entry.id
    if entry.learnedName then return entry.learnedName, "Learned in game" end
    if kind == "n" then
        local n = DB.npcs[id]
        return n and n[1] or ("NPC " .. id), n and n[2]
    elseif kind == "o" then
        return DB.objs[id] or ("Object " .. id)
    elseif kind == "i" then
        local it = DB.items[id]
        -- what drops it is listed under "Dropped by:" in the panel, not repeated here
        return it and it[1] or ("Item " .. id)
    end
    return "Dungeon: " .. (DB.dungeons[id] or ("Area " .. id)), "Quests given inside - enter here"
end

function Data.QuestName(id)
    local d = DB.quests[id]
    if d then return d[1] end
    local l = AQ.shared.learned[id]
    return l and l.n or ("Quest " .. id)
end

function Data.RequiredLevel(id)
    local d = DB.quests[id]
    return d and d[3] or 0
end

function Data.HasMap(uiMapId)
    return DB ~= nil and DB.maps[uiMapId] ~= nil
end

-- What drops a quest-starting item: a list of "Name (lvl 5-6) - 12%" lines and how many more there are.
function Data.ItemDrops(itemId)
    local it = DB.items[itemId]
    if not it then return end
    local lines = it[2]
    if type(lines) == "string" then lines = { lines } end
    return lines, it[3]
end

-- Quest record for this character, or nil when the race/class cannot take the quest.
local recs = {}
local function Rec(id)
    local r = recs[id]
    if r ~= nil then return r or nil end
    local d = DB.quests[id]
    if not d or not (HasBit(d[5], raceMask) and HasBit(d[6], classFlag)) then
        recs[id] = false
        return nil
    end
    r = {
        id = id, ql = d[2], req = d[3] or 0, maxl = d[4], rep = ((d[7] or 0) % 2) >= 1,
        preS = d[8], preG = d[9], excl = d[10], parent = (d[11] and d[11] > 0) and d[11] or nil,
        sk = d[12], mr = d[13], xr = d[14], ev = d[15], tag = d[16], grp = d[17],
        cls = (d[6] and d[6] ~= 0) or nil, clsMask = (d[6] and d[6] ~= 0) and d[6] or nil,
    }
    recs[id] = r
    return r
end

-- Quests the player has been offered in game that the bundled database lacks (or lacks that giver for):
-- AQ.shared.learned[questId] = { n = title, l = level, k = "n"|"o", id = giver id, name = giver name, m = uiMapId, x, y }
local function LearnedRec(id, l)
    return { id = id, ql = l.l, req = 0, rep = false }
end

local mapCache = {}

-- Which quests each giver is known to offer in the bundled data ("n123" -> { [questId] = true }).
local giverQuests
local function GiverQuests()
    if giverQuests then return giverQuests end
    giverQuests = {}
    for _, list in pairs(DB.maps) do
        for _, e in ipairs(list) do
            if e[3] == "n" or e[3] == "o" then
                local key = e[3] .. e[4]
                local set = giverQuests[key]
                if not set then set = {} giverQuests[key] = set end
                for _, qid in ipairs(e[5]) do set[qid] = true end
            end
        end
    end
    return giverQuests
end

function Data.IsKnownGiver(kind, id, questId)
    local set = GiverQuests()[kind .. id]
    return set ~= nil and set[questId] == true
end

function Data.InvalidateMap(uiMapId)
    mapCache[uiMapId] = nil
end

function Data.InvalidateAll()
    mapCache = {}
end

-- Giver spots of one map, with their quest records; built on first use.
local function Entries(uiMapId)
    local cached = mapCache[uiMapId]
    if cached then return cached end
    cached = {}
    for _, e in ipairs(DB.maps[uiMapId] or {}) do
        local kind, id = e[3], e[4]
        local friendly = kind == "n" and DB.npcs[id] and DB.npcs[id][3]
        local hostile = (faction == "Alliance" and friendly == "H") or (faction == "Horde" and friendly == "A")
        if not hostile then
            local list
            for _, qid in ipairs(e[5]) do
                local rec = Rec(qid)
                if rec then
                    list = list or {}
                    list[#list + 1] = rec
                end
            end
            if list then
                cached[#cached + 1] = { kind = kind, id = id, map = uiMapId, x = e[1] / 100, y = e[2] / 100, quests = list, rep = e[6] == 1 }
            end
        end
    end
    -- quests learned in game on this map, grouped by giver and spot
    local groups = {}
    for qid, l in pairs(AQ.shared.learned) do
        if l.m == uiMapId then
            local key = l.k .. l.id .. ":" .. l.x .. ":" .. l.y
            local g = groups[key]
            if not g then
                g = { kind = l.k, id = l.id, map = uiMapId, x = l.x / 100, y = l.y / 100, quests = {}, learnedName = l.name or "Quest giver" }
                groups[key] = g
                cached[#cached + 1] = g
            end
            g.quests[#g.quests + 1] = Rec(qid) or LearnedRec(qid, l)
        end
    end
    mapCache[uiMapId] = cached
    return cached
end

---------------------------------------------------------------------------------------------
-- Per-character filtering

local function GreenRange()
    if C_QuestLog and C_QuestLog.GetTrivialRange then return C_QuestLog.GetTrivialRange() end
    if GetQuestGreenRange then return GetQuestGreenRange() end
    return 8
end

local function IsCompleted(id)
    if C_QuestLog and C_QuestLog.IsQuestFlaggedCompleted then return C_QuestLog.IsQuestFlaggedCompleted(id) end
    if IsQuestFlaggedCompleted then return IsQuestFlaggedCompleted(id) end
    return false
end

local function IsInLog(id)
    local index
    if C_QuestLog and C_QuestLog.GetLogIndexForQuestID then
        index = C_QuestLog.GetLogIndexForQuestID(id)
    elseif GetQuestLogIndexByID then
        index = GetQuestLogIndexByID(id)
    end
    return index ~= nil and index > 0
end

-- Profession skill levels by skill line id.
local function PlayerSkills()
    local t = {}
    if GetProfessions and GetProfessionInfo then
        for _, index in pairs({ GetProfessions() }) do
            local _, _, rank, _, _, _, skillLine = GetProfessionInfo(index)
            if skillLine and rank then t[skillLine] = rank end
        end
    end
    if C_SkillInfo and C_SkillInfo.GetNumSkillLines then
        for i = 1, C_SkillInfo.GetNumSkillLines() do
            local info = C_SkillInfo.GetSkillLineInfo(i)
            if info and not info.isHeader and info.skillID then
                t[info.skillID] = math.max(t[info.skillID] or 0, info.rank or 0)
            end
        end
    end
    return t
end
Data.PlayerSkills = PlayerSkills

-- Reputation value with a faction (-42000..42000). Factions you have not met count as neutral (0),
-- except the few that start hostile.
local STARTS_BELOW_NEUTRAL = { [87] = true, [576] = true, [910] = true, [941] = true, [970] = true, [978] = true,
    [1015] = true, [1171] = true }
local function RepValue(factionId)
    local value
    if C_Reputation and C_Reputation.GetFactionDataByID then
        local d = C_Reputation.GetFactionDataByID(factionId)
        value = d and d.currentStanding
    elseif GetFactionInfoByID then
        value = select(6, GetFactionInfoByID(factionId))
    end
    if value == nil then value = STARTS_BELOW_NEUTRAL[factionId] and -36000 or 0 end
    return value
end

-- Returns the displayed quest level, whether it is locked (level too low to accept yet) and
-- whether it is trivial (grey), or nil to hide the quest.
local function Evaluate(q, ctx)
    local db, pl = ctx.db, ctx.pl
    local req = q.req
    local ql = q.ql
    if not ql or ql < 0 then ql = math.max(pl, req) end   -- scaling quests

    if q.maxl and q.maxl > 0 and pl > q.maxl then return end
    if q.ev and not (db.showEventQuests and AQ.Events.IsActive(q.ev)) then return end
    if q.rep then
        if not db.showRepeatable then return end
    elseif ctx.completed(q.id) then
        return
    end
    if ctx.inLog(q.id) then return end

    if not db.showAll and math.max(ql, req) > pl + db.levelsAbove then return end
    local locked = req > pl                    -- cannot be picked up yet
    local trivial = ql < pl - ctx.green        -- grey for this character
    if trivial and db.hideLowLevel then return end

    if q.parent and not ctx.inLog(q.parent) then return end
    if q.preS then
        local met = false
        for _, p in ipairs(q.preS) do
            if ctx.completed(p) then met = true break end
        end
        if not met then return end
    elseif q.preG then
        for _, p in ipairs(q.preG) do
            if not ctx.completed(p) then return end
        end
    end
    if q.excl then
        for _, e in ipairs(q.excl) do
            if ctx.completed(e) or ctx.inLog(e) then return end
        end
    end
    if db.checkSkills and q.sk then
        local have = ctx.skills()[q.sk[1]]
        if not have or have < (q.sk[2] or 0) then return end
    end
    if db.checkReputation then
        if q.mr and ctx.rep(q.mr[1]) < q.mr[2] then return end
        if q.xr and ctx.rep(q.xr[1]) >= q.xr[2] then return end
    end
    return ql, locked, trivial
end

local function Memo(fn)
    local cache = {}
    return function(id)
        local v = cache[id]
        if v == nil then
            v = fn(id) and true or false
            cache[id] = v
        end
        return v
    end
end

local function Once(fn)
    local done, value
    return function()
        if not done then value, done = fn(), true end
        return value
    end
end

local function ValueMemo(fn)
    local cache = {}
    return function(key)
        local v = cache[key]
        if v == nil then
            v = fn(key)
            cache[key] = v
        end
        return v
    end
end

-- Pins for one map: { { entry, quests = { {id, level, locked, trivial, rep}, ... }, top }, ... }
-- `top` is the quest that styles the pin: the highest level one that is not trivial (or the
-- highest level one when everything is trivial).
function Data.GetPins(uiMapId)
    local pins = {}
    if not Data.ready then return pins end
    local ctx = {
        db = AQ.db,
        pl = UnitLevel("player"),
        green = GreenRange(),
        completed = Memo(IsCompleted),
        inLog = Memo(IsInLog),
        skills = Once(PlayerSkills),
        rep = ValueMemo(RepValue),
    }
    local db = ctx.db
    local ignored = AQ.shared.ignored
    for _, entry in ipairs(Entries(uiMapId)) do
      if not ((entry.kind == "d" and not db.showDungeonQuests)
              or (entry.kind == "i" and not db.showDropQuests)
              or ignored.givers[entry.kind .. entry.id]) then
        local shown, top
        for _, q in ipairs(entry.quests) do
            local level, locked, trivial
            if not ignored.quests[q.id] then level, locked, trivial = Evaluate(q, ctx) end
            if level then
                local item = { id = q.id, level = level, locked = locked, trivial = trivial, rep = q.rep,
                    tag = q.tag, cls = q.cls, prof = q.sk ~= nil, ev = q.ev,
                    req = q.req, maxl = q.maxl, clsMask = q.clsMask, sk = q.sk, mr = q.mr, xr = q.xr,
                    scaled = q.ql ~= nil and q.ql < 0, grp = q.grp or AQ.shared.groupSizes[q.id] }
                -- the quest-type filter (Pins.lua knows the types)
                if not (AQ.TypeHidden and AQ.TypeHidden(item, entry.kind)) then
                    shown = shown or {}
                    shown[#shown + 1] = item
                    if not top
                        or (top.trivial and not trivial)
                        or (top.trivial == trivial and level > top.level) then
                        top = item
                    end
                end
            end
        end
        if shown then
            table.sort(shown, function(a, b)
                if a.level ~= b.level then return a.level < b.level end
                return a.id < b.id
            end)
            pins[#pins + 1] = { entry = entry, quests = shown, top = top }
        end
      end
    end
    return pins
end

-- Ids of every map that has giver spots.
function Data.MapIds()
    local list = {}
    if DB then
        for uiMapId in pairs(DB.maps) do list[#list + 1] = uiMapId end
    end
    return list
end
